
% Generated by ChatGPT

fs = 1000;                 % <- Twoje fs
t = (0:10*fs-1)'/fs;       % 10 s
x_clean = sin(2*pi*5*t) + 0.3*sin(2*pi*11*t);  % przykładowy sygnał

% Maska: 1.5 s on, 1 s off
on_dur = 1.5; off_dur = 1.0;
pattern = [true(round(on_dur*fs),1); false(round(off_dur*fs),1)];
mask = repmat(pattern, ceil(numel(t)/numel(pattern)), 1);
mask = mask(1:numel(t));

x_with_gaps = x_clean;
x_with_gaps(~mask) = NaN;  % <<< bardzo ważne: NaN, nie zera!

% Wybierz rząd AR (patrz wskazówki niżej)
p = 40;

x_filled = fill_gaps_ar(x_with_gaps, fs, p);

% Podgląd
figure;
plot(t, x_with_gaps); hold on;
plot(t, x_filled, '--');
legend('z przerwami','po AR-fill');
xlabel('t [s]');
ylabel('amplituda');
title(sprintf('Uzupełnianie przerw AR(p=%d)', p));
grid on;